-- Contenu de fin de jeu : chapitres de campagne 16 à 20 (étages 151-200)
-- et étages 11 à 20 des quatre tours, calibrés au simulateur vers une équipe
-- de 3 légendaires n70 en équipement légendaire (campaign.definitions.ts,
-- tower.definitions.ts, prisma/seed/balance-calibration.ts).
--
-- Les tours n'ont plus de boss : l'étage 10 perd son unité AOE_3 et suit la
-- courbe linéaire 9 → 20 (ses ennemis seuls sont réécrits, butin et sprites
-- inchangés). Le reste de l'existant ne bouge pas : les 150 étages de
-- campagne et les étages 1 à 9 des tours (legacy-content-frozen.test.ts).
-- Le déblocage suit la progression stockée : un joueur qui a battu 15-10
-- voit 16-1, un joueur à l'étage 10 d'une tour voit le 11 ; l'étage 10 reste
-- franchi pour qui l'a franchi.
--
-- Libellés de boss : « 3-10 Boss » devient « 3-10 », l'écran marquant déjà
-- le boss (`isBoss`).
--
-- Migration de DONNÉES (le déploiement ne seede jamais), générée depuis les
-- définitions. Idempotente : insertion seulement si la ligne manque.

ON CONFLICT (chapter, "index") DO NOTHING;

ON CONFLICT (element, "index") DO NOTHING;

UPDATE "TowerFloor" SET "enemyTeam" = '[{"baseHp":48623,"baseAtk":8140,"baseDef":410,"baseSpd":120,"level":1,"palier":1,"attackPattern":"BASIC","appearance":"monsters/minotaurs/MINO-008","element":"FIRE"},{"baseHp":48623,"baseAtk":8140,"baseDef":410,"baseSpd":120,"level":1,"palier":1,"attackPattern":"BASIC","appearance":"monsters/wyverns/WYVN-008","element":"FIRE"},{"baseHp":48623,"baseAtk":8140,"baseDef":410,"baseSpd":120,"level":1,"palier":1,"attackPattern":"BASIC","appearance":"monsters/kobolds/KOBO-001","element":"FIRE"}]'::jsonb
WHERE element = 'FIRE'::"CardElement" AND "index" = 10;

UPDATE "TowerFloor" SET "enemyTeam" = '[{"baseHp":48623,"baseAtk":8140,"baseDef":410,"baseSpd":120,"level":1,"palier":1,"attackPattern":"BASIC","appearance":"monsters/hydras/HYDRA-005","element":"WATER"},{"baseHp":48623,"baseAtk":8140,"baseDef":410,"baseSpd":120,"level":1,"palier":1,"attackPattern":"BASIC","appearance":"monsters/krakens/KRAK-010","element":"WATER"},{"baseHp":48623,"baseAtk":8140,"baseDef":410,"baseSpd":120,"level":1,"palier":1,"attackPattern":"BASIC","appearance":"monsters/slimes/SLIME-001","element":"WATER"}]'::jsonb
WHERE element = 'WATER'::"CardElement" AND "index" = 10;

UPDATE "TowerFloor" SET "enemyTeam" = '[{"baseHp":48623,"baseAtk":8140,"baseDef":410,"baseSpd":120,"level":1,"palier":1,"attackPattern":"BASIC","appearance":"monsters/wolves/WOLF-010","element":"NATURE"},{"baseHp":48623,"baseAtk":8140,"baseDef":410,"baseSpd":120,"level":1,"palier":1,"attackPattern":"BASIC","appearance":"monsters/mimics/MIMC-001","element":"NATURE"},{"baseHp":48623,"baseAtk":8140,"baseDef":410,"baseSpd":120,"level":1,"palier":1,"attackPattern":"BASIC","appearance":"monsters/mushrooms/MYCO-001","element":"NATURE"}]'::jsonb
WHERE element = 'NATURE'::"CardElement" AND "index" = 10;

UPDATE "TowerFloor" SET "enemyTeam" = '[{"baseHp":48623,"baseAtk":8140,"baseDef":410,"baseSpd":120,"level":1,"palier":1,"attackPattern":"BASIC","appearance":"monsters/basilisks/BSLK-007","element":"EARTH"},{"baseHp":48623,"baseAtk":8140,"baseDef":410,"baseSpd":120,"level":1,"palier":1,"attackPattern":"BASIC","appearance":"monsters/basilisks/BSLK-001","element":"EARTH"},{"baseHp":48623,"baseAtk":8140,"baseDef":410,"baseSpd":120,"level":1,"palier":1,"attackPattern":"BASIC","appearance":"monsters/basilisks/BSLK-002","element":"EARTH"}]'::jsonb
WHERE element = 'EARTH'::"CardElement" AND "index" = 10;


WITH r AS (
  SELECT gen_random_uuid()::text, 15, 400, 0, 'RARE'::"CardRarity"
  WHERE NOT EXISTS (SELECT 1 FROM "Achievement" WHERE key = 'chapter_reached_17')
  RETURNING id
)
SELECT gen_random_uuid()::text, 'chapter_reached_17', 'Éclipse', 'Eclipse', 'Atteindre le chapitre 17.', 'Reach chapter 17.', 'campaign', 3, false, '{"type":"CAMPAIGN_CHAPTER_REACHED","threshold":17}'::jsonb, 14, true, r.id
FROM r;

WITH r AS (
  SELECT gen_random_uuid()::text, 30, 800, 0, 'EPIC'::"CardRarity"
  WHERE NOT EXISTS (SELECT 1 FROM "Achievement" WHERE key = 'chapter_reached_20')
  RETURNING id
)
SELECT gen_random_uuid()::text, 'chapter_reached_20', 'Trône du Chaos', 'Throne of Chaos', 'Atteindre le chapitre 20.', 'Reach chapter 20.', 'campaign', 4, false, '{"type":"CAMPAIGN_CHAPTER_REACHED","threshold":20}'::jsonb, 15, true, r.id
FROM r;

UPDATE "CampaignStage"
SET "labelFr" = chapter || '-' || "index", "labelEn" = chapter || '-' || "index"
WHERE "isBoss" = true;
